(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zn-sj-prepa-sp-j4-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zn-sj-prepa-sp-j4-idesfm\",\n \"titre\": \"Préparation D.E (J) · J4 Santé publique IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 43,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Santé publique · Prépa D.E J4 (IDE/SFM)\",\n     \"slug\": \"prepa-sp-j4-idesfm\",\n     \"pages\": \"\",\n     \"count\": 43,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Santé publique\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le seuil d'alerte est le niveau à partir duquel la riposte doit être déclenchée face à une menace d'épidémie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le seuil d'alerte déclenche la vigilance : notification, investigation, vérification des stocks et préparation. C'est le seuil épidémique qui déclenche la riposte.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'accessibilité aux soins consiste à mettre les soins de santé à proximité des populations et à un prix non exorbitant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'accessibilité des soins ne se limite pas à la proximité géographique et au prix : elle est aussi culturelle et fonctionnelle (soins acceptables, disponibles, horaires adaptés…). L'énoncé est donc incomplet.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le non-respect de la politique du flacon entamé est un facteur évitable de perte de vaccins.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». En PEV, les pertes en flacons non ouverts (rupture de la chaîne du froid, péremption, casse, vol) sont dites évitables ; les pertes liées aux flacons entamés sont classées avec les pertes en flacons ouverts. Remarque : L'énoncé prête à discussion : respecter la politique du flacon entamé permet justement de réduire les pertes.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En Côte d'Ivoire la politique des SSP comprend deux composantes préventives et trois composantes curatives\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les soins de santé primaires (Alma-Ata, 1978) comprennent 8 composantes essentielles (éducation pour la santé, alimentation, eau et assainissement, SMI/PF, vaccination, lutte contre les endémies locales, traitement des maladies courantes, médicaments essentiels), et non 2 + 3.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On peut administrer le VPI à tous les enfants ayant un âge compris entre 0 et 23 mois sans exception.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le VPI est un vaccin inactivé, sans risque de polio vaccinale, qui peut être donné à tous les enfants de la cible (y compris immunodéprimés). Remarque : « Sans exception » est absolu : une réaction allergique grave à une dose précédente reste une contre-indication.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les doses de vaccins perdues pour que la vaccination ait lieu sont considérées comme des doses sacrifiées\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Ouvrir un flacon multidose pour vacciner un petit nombre d'enfants fait perdre les doses restantes : ce sont des doses « sacrifiées » pour ne pas manquer d'occasion de vacciner.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Plus le taux de perte est élévé, moins le facteur de perte est élevé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Facteur de perte = 100 / (100 – taux de perte). Quand le taux de perte augmente, le facteur de perte augmente aussi.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les cas de poliomyélite à virus de type sauvage, l'excrétion virale dans les selles augmente au-delà de deux semaines après le début de la paralysie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'excrétion du poliovirus dans les selles est maximale au début de la paralysie puis diminue : c'est pourquoi les selles sont prélevées dans les 14 jours suivant le début de la paralysie.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sujet d'intérêt en épidémiologie est le malade.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'épidémiologie étudie la santé des populations (groupes), et non le malade pris individuellement, qui relève de la clinique.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En matière de vaccination, l'intervalle minimum existe\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Entre deux doses d'un même antigène (par exemple Penta 1, 2, 3), il faut respecter un intervalle minimum de 4 semaines ; il n'y a pas d'intervalle maximum.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les centres antituberculeux sont situés au niveau périphérique du versant administratif du PNLT\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les centres antituberculeux sont des structures de dépistage et de traitement (versant technique/opérationnel du programme), situés au niveau intermédiaire, pas au niveau périphérique du versant administratif.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le superviseur ayant le style autocratique cherche à tout comprendre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le superviseur autocratique centralise : il veut tout savoir, tout contrôler et décider seul, sans déléguer.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'intervention en approche épidémiologique repose sur le contrôle, l'éradication, l'élimination et la maîtrise de la maladie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Ce sont les niveaux d'objectifs de la lutte contre une maladie : maîtrise/contrôle (réduire), élimination (supprimer dans une zone), éradication (supprimer partout).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le processus d'évacuation des ordures ménagères comprend le stockage et le ramassage.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La gestion des ordures ménagères comprend la pré-collecte et le stockage, la collecte (ramassage), le transport et le traitement ou l'élimination.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de létalité permet d'évaluer la qualité de la prise en charge des malades\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le taux de létalité (décès parmi les malades) reflète la gravité de la maladie et la qualité de la prise en charge des cas.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La participation communautaire a été prônée en 1985 à Bamako pour garantir la mise en œuvre et la pérennisation d'un système de financement communautaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'Initiative de Bamako date de 1987 (et non 1985).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'absence d'humidité dans le logement est un critère de salubrité de l'habitat relatif aux besoins physiologiques\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un logement sain doit satisfaire les besoins physiologiques de l'occupant : aération, éclairage, température, absence d'humidité.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"- Le bassin de desserte correspond à une zone située dans un rayon de 15 km autour d'un centre de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai » : le bassin de desserte correspond à la population vivant dans un rayon de 15 km autour du centre de santé. Remarque : Ne pas confondre avec l'accessibilité géographique (population à moins de 5 km).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le district est l'unité sanitaire décentralisée regroupant tous les services sanitaires publics tant en milieu urbain que rural\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le district sanitaire regroupe l'ensemble des structures de santé de sa zone, publiques mais aussi privées, confessionnelles et communautaires, et pas seulement les services publics.\\n\\nSource : (explication hors cours du projet) Questions à choix\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nombre de dose et la voie d'administration correcte du vaccin Rotarix est:\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Deux doses de 0.5 ml en IM\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Trois doses de 0.5 ml en IM\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Deux doses de 2 ml par voie orale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Trois doses de 2 ml par voie orale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Deux doses de 2 ml par voie orale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le vaccin rotavirus Rotarix se donne par voie orale en 2 doses (à 6 et 10 semaines dans le PEV). Remarque : Le volume habituel d'une dose de Rotarix est de 1,5 ml ; C reste la seule option avec 2 doses par voie orale.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les problèmes suivants causés par l'abus des drogues, indiquez ceux qui sont d'ordre sanitaire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'absentéisme scolaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hallucination\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les accidents de la voie publique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le délire\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le suicide\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"L'asthénie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L'hallucination ; D. Le délire ; F. L'asthénie\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Hallucinations, délire et asthénie sont des atteintes de la santé de la personne. L'absentéisme scolaire et les accidents de la voie publique sont des problèmes sociaux. Remarque : Le suicide n'est pas retenu par la correction nationale de la Prépa DE (les J).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, cocher celles qui sont les missions assignées à un district sanitaire : Entourer la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Evaluation des agents de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Promotion des soins de santé primaires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Suivi et évaluation des activités\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Coordination des activités sanitaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Promotion des soins de santé primaires ; C. Suivi et évaluation des activités ; D. Coordination des activités sanitaires\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le district met en œuvre les SSP, coordonne les activités de santé de sa zone et en assure le suivi et l'évaluation. L'évaluation individuelle des agents n'est pas une mission du district en tant que tel.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le système d'évacuation des excréta le plus couramment utilisé sans entraînement des matières fécales est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fosse septique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La fosse d'aisance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La latrine à fosse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le réseau d'égouts\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La latrine à fosse\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La latrine à fosse (sèche) n'utilise pas d'eau pour entraîner les matières ; fosse septique et égouts sont des systèmes à chasse d'eau. C'est le système le plus répandu.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle méthode permet de lutter contre les moustiques adultes ?-\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Combler les flaques d'eau\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Curer les caniveaux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dormir sous une moustiquaire imprégnée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vider les récipients contenant de l'eau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dormir sous une moustiquaire imprégnée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La moustiquaire imprégnée d'insecticide protège et tue les moustiques adultes. Combler les flaques, curer les caniveaux et vider les récipients détruisent les gîtes larvaires (lutte anti-larvaire).\\n\\nSource : SONU L3, Paludisme et grossesse (prévention) p. 90-91 (partiellement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les antigènes ci-dessous, cochez ceux qui ont pour site d'administration la cuisse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"BCG ; Td ; PCV 13\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"VPI ; Rota ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"DN hépatite ; VPI ; Men A ; VAP\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"VPO ; HPV ; RR\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. DN hépatite ; VPI ; Men A ; VAP\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Chez le nourrisson, les vaccins injectables du PEV (Penta/DTC-HépB, VPI, PCV, Men A…) se font dans la face antéro-latérale de la cuisse. Les autres groupes contiennent un vaccin oral (Rota, VPO), le BCG (intradermique au bras) ou le Td (bras).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs susceptibles d'influencer le changement social de comportement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La perception\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le milieu social\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La culture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les caractéristiques personnelles et psychologiques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Le milieu social ; C. La culture\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Pour un changement social de comportement, on retient les facteurs de l'environnement social : le milieu social et la culture. La perception et les caractéristiques personnelles sont des facteurs individuels.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de paralysie flasque aigue un prélèvement des selles se fait :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Entre J10 et J14\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Entre J14 et J60\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Entre J61 et 06 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Après 06 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Entre J10 et J14 ; B. Entre J14 et J60\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient A et B. Remarque : Selon les directives de surveillance des PFA, les 2 échantillons de selles se prélèvent dans les 14 jours suivant le début de la paralysie ; J60 correspond à l'examen de suivi. Le choix B est à confirmer avec le cours de santé publique.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une endémie est un phénomène :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Limité dans le temps et limité dans l'espace\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Illimité dans le temps et illimité dans l'espace\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Limité dans le temps et illimité dans l'espace\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Illimité dans le temps et limité dans l'espace\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Illimité dans le temps et limité dans l'espace\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'endémie est la présence habituelle d'une maladie dans une zone donnée : durable (illimitée dans le temps) mais localisée. L'épidémie est limitée dans le temps ; la pandémie s'étend à plusieurs pays ou continents.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces antigènes suivants, lequel est vivant atténué ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Td\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"VPO\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"VPI\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. VPO\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le VPO (polio oral) contient des virus vivants atténués. Le VPI est un vaccin inactivé ; le Td contient des anatoxines.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La MOBSOC a pour but :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Promouvoir la santé communautaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Changer une situation sociale et communautaire en un sens favorable à la société selon ses valeurs et motivations\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inciter la communauté à se mobiliser et à mobiliser leurs propres moyens pour remédier aux problèmes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Changer une situation sociale et communautaire en un sens favorable à la société selon ses valeurs et motivations\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La mobilisation sociale vise à changer une situation sociale et communautaire dans un sens favorable, en s'appuyant sur les valeurs et motivations de la société. Les options A et C décrivent des moyens ou des effets plus limités.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les actions suivantes, une seule permet d'améliorer la saveur et l'odeur de l'eau :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'ébullition\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Usage de charbon de bois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La sédimentation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La filtration\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'ionisation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Usage de charbon de bois\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le charbon (de bois ou actif) adsorbe les matières qui donnent goût et odeur à l'eau. L'ébullition désinfecte, la sédimentation et la filtration clarifient.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, identifier ceux qui constituent des différentes catastrophes naturelles :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La guerre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les cyclones\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les tremblements de terre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le tsunami\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les graves accidents de circulation\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Les génocides\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Les cyclones ; C. Les tremblements de terre ; D. Le tsunami\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Cyclones, tremblements de terre et tsunamis sont d'origine naturelle. Guerre, génocide et accidents graves de circulation sont des catastrophes d'origine humaine.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les vaccins du PEV qui sont sensibles à la lumière sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"BCG\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"RR\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"VAA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Penta\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. BCG ; B. RR\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Les vaccins lyophilisés BCG et RR (rougeole-rubéole) sont sensibles à la lumière : on les protège du soleil et de la lumière vive, surtout après reconstitution. Remarque : Le VAA (fièvre jaune) est aussi souvent cité comme sensible à la lumière ; la correction nationale de la Prépa DE (les J) ne retient que BCG et RR.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Trouvez les bonnes combinaisons entre les dates et les évènements\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \": (1, f) ; (2, b) ; (3, c) ; (4, d) ; (5, a) ; (6, e)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \": (1, f) ; (2, c) ; (3, b) ; (4, a) ; (5, d) ; (6, e)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \": (1, e) ; (2, b) ; (3, c) ; (4, d) ; (5, a) ; (6, f)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \": (1, c) ; (2, f) ; (3, a) ; (4, b) ; (5, e) ; (6, d)\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \": (1, d) ; (2, e) ; (3, f) ; (4, c) ; (5, b) ; (6, a)\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Option 2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. : (1, f) ; (2, b) ; (3, c) ; (4, d) ; (5, a) ; (6, e)\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient la combinaison A. Remarque : Dans le sujet, la liste des dates (1 à 6) et des événements (a à f) n'apparaît pas : seules les combinaisons sont visibles. L'explication ne peut donc pas être détaillée. « Option 2 » est un choix vide laissé dans le sujet.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les maladies suivantes, indiquez celles qui sont sous surveillance en Côte d'Ivoire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le cholera\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le paludisme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La fièvre hémorragique virale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La dracunculose\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les infections respiratoires aiguës\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Les infections urinaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le cholera ; C. La fièvre hémorragique virale ; D. La dracunculose\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Choléra et fièvres hémorragiques virales sont des maladies à potentiel épidémique à déclaration immédiate ; la dracunculose (ver de Guinée) est une maladie en voie d'éradication sous surveillance. La correction nationale de la Prépa DE (les J) ne retient pas le paludisme ni les IRA.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les critères suivants, indiquez ceux qui permettent de sélectionner un problème prioritaire de santé :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'ampleur du problème\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La gravité du problème\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La population totale de la localité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le niveau d'instruction des populations\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La vulnérabilité du problème\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"La durée des interventions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. L'ampleur du problème ; B. La gravité du problème ; E. La vulnérabilité du problème\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Un problème de santé prioritaire se choisit selon son ampleur (fréquence), sa gravité et sa vulnérabilité (possibilité d'agir avec les moyens disponibles).\\n\\nSource : (explication hors cours du projet) ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Quel est le taux d'accroissement annuel de la population de Sinikosson ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,02%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0,2 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 2%\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Accroissement sur un an = (5100 – 5000) / 5000 × 100 = 2 %.\\n\\nSource : (calcul à partir des données de l'énoncé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Quelle est la population totale en 2021 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5100\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5200\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5202\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 5202\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La population au 1er janvier 2021 (5100) augmente de 2 % pendant l'année : 5100 × 1,02 = 5202 habitants en fin d'année 2021.\\n\\nSource : (calcul à partir des données de l'énoncé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Quelle est la population moyenne en 2021 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5151\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5150\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5050\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5253\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 5151\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Population moyenne = (population de début d'année + population de fin d'année) / 2 = (5100 + 5202) / 2 = 5151.\\n\\nSource : (calcul à partir des données de l'énoncé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Quel est le nombre de femmes en âge de reproduction en 2021 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1020\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1030\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1041\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 1041\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les femmes en âge de reproduction représentent environ 20 % de la population : 5202 × 0,20 = 1040,4, arrondi à 1041. Remarque : Le taux de 20 % est le taux habituellement utilisé ; l'arrondi se fait à l'unité supérieure.\\n\\nSource : (calcul ; le pourcentage de 20 % n'est pas dans l'énoncé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Quel est le nombre des enfants de 0 à 23 mois en 2021\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"352\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"256\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"355\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"445\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 355\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La cible 0-23 mois se calcule en appliquant à la population le pourcentage national de cette tranche d'âge ; la correction nationale de la Prépa DE (les J) retient 355. Remarque : Le pourcentage utilisé n'est pas donné dans le sujet : le calcul ne peut pas être refait avec les seules données de l'énoncé.\\n\\nSource : (calcul ; le pourcentage n'est pas dans l'énoncé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Calculez le Besoin Théorique mensuel de RR pour vacciner ces enfants de 0 à 23 mois\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"65 doses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"66 doses\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"70 doses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"80 doses\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"64 doses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 66 doses\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Besoin théorique mensuel = cible × nombre de doses × facteur de perte / 12. Avec 355 enfants, 2 doses de RR et un facteur de perte de 1,11 (taux de perte de 10 %) : 355 × 2 × 1,11 / 12 ≈ 65,7, soit 66 doses. Remarque : Le facteur de perte de 1,11 n'est pas donné dans l'énoncé ; c'est la valeur qui retrouve 66 doses.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j4-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS Cas clinique / étude de cas Après votre formation, vous êtes affecté(e) au centre de santé de Sinikosson où travaillent deux infirmiers et une sage-femme diplômé(e)s d'état. La population totale de ce centre de santé a été estimée à 5000 habitants au 31/12/2019 et à 5100 habitants au 1er/01/2021. Pendant l'année 2021, les données sanitaires suivantes ont été relevées dans ce village : - 25 naissances enregistrées dont 04 mort-nés ; - 105 cas de paludisme et 35 cas de diarrhées ; - 03 décès des femmes enceintes dont 01 à la suite d'une chute sur la route du champ ; - 06 femmes décédées dont 04 après 5 semaines de suites de couches et 02 après 7 semaines de suites de couches ; Par ailleurs, le dispensaire et la maternité disposent de 18 lits et le ratio personnel infirmier/lit du dispensaire est de 0,2. À partir du texte ci-dessus répondre aux questions ci-dessous\",\n       \"text\": \"Calculez le nombre de lits disponibles à la maternité .\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 lits\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 lits\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8 lits\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12 lits\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 8 lits\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Ratio personnel infirmier/lit du dispensaire = 0,2, avec 2 infirmiers : lits du dispensaire = 2 / 0,2 = 10. Lits de la maternité = 18 – 10 = 8.\\n\\nSource : (calcul à partir des données de l'énoncé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Santé publique)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
